3599	
3600	/**
3601	 * 计算采购单各商品的有效到货（未冲销到货-未冲销退货）、有效退货、有效取消与待到货量。
3602	 * 有效取消含两部分采购转单效应：本单作为原单由未冲销转单转出的量；
3603	 * 本单作为目的单且来源转单已冲销时的全部订购量（目的单整单关闭、待收归零）。
3604	 * 累计总量可超过安全整数范围（反复退货、补收），一律用 BigInt 精确累计，
3605	 * 合计与记录枚举顺序无关；有效退货合计即使超过安全整数范围也能完整显示。
3606	 */
3607	function purchaseProgress(store: Store, poId: string): {
3608	  effective: Record<string, bigint>;
3609	  returned: Record<string, bigint>;
3610	  cancelled: Record<string, bigint>;
3611	  remaining: Record<string, bigint>;
3612	} {
3613	  const revOfOrig = nullProto<Record<string, string>>();
3614	  for (const [revId, rec] of Object.entries(store.reversals)) revOfOrig[rec.orig] = revId;
3615	  const effective = nullProto<Record<string, bigint>>();
3616	  for (const [arrId, arr] of Object.entries(store.arrivals)) {
3617	    if (arr.poId !== poId || revOfOrig[arrId] !== undefined) continue;
3618	    for (const [pid, q] of Object.entries(arr.qty)) effective[pid] = (effective[pid] ?? 0n) + BigInt(q);
3619	  }
3620	  const returned = nullProto<Record<string, bigint>>();
3621	  for (const [retId, ret] of Object.entries(store.returns)) {
3622	    if (ret.poId !== poId || revOfOrig[retId] !== undefined) continue;
3623	    for (const [pid, q] of Object.entries(ret.qty)) {
3624	      returned[pid] = (returned[pid] ?? 0n) + BigInt(q);
3625	      effective[pid] = (effective[pid] ?? 0n) - BigInt(q); // 未冲销退货抵减有效到货
3626	    }
3627	  }
3628	  const cancelled = nullProto<Record<string, bigint>>();
3629	  for (const [canId, can] of Object.entries(store.cancels)) {
3630	    if (can.poId !== poId || revOfOrig[canId] !== undefined) continue;
3631	    for (const [pid, q] of Object.entries(can.qty)) cancelled[pid] = (cancelled[pid] ?? 0n) + BigInt(q);
3632	  }
3633	  const po = store.purchases[poId];
3634	  // 转出：本单作为原单由未冲销转单转出的量计入有效取消
3635	  for (const t of Object.values(store.poTransfers)) {
3636	    if (t.origPo !== poId || revOfOrig[t.tId] !== undefined) continue;
3637	    for (const [pid, q] of Object.entries(t.qty)) cancelled[pid] = (cancelled[pid] ?? 0n) + BigInt(q);
3638	  }
3639	  // 目的单的来源转单已冲销：全部订购量计为取消、待收归零
3640	  if (po.fromTransfer !== undefined && revOfOrig[po.fromTransfer] !== undefined) {
3641	    for (const [pid, q] of Object.entries(po.ordered)) cancelled[pid] = (cancelled[pid] ?? 0n) + BigInt(q);
3642	  }
3643	  const remaining = nullProto<Record<string, bigint>>();
3644	  for (const [pid, ordered] of Object.entries(po.ordered)) {
3645	    remaining[pid] = BigInt(ordered) - (effective[pid] ?? 0n) - (cancelled[pid] ?? 0n);
3646	  }
3647	  return { effective, returned, cancelled, remaining };
3648	}
3649	
3650	/**
3651	 * 单商品采购状态。无取消时保持原有展示（未到货/部分到货/收齐）；
3652	 * 有取消时区分仍待收与已结清：待到货为零但含取消的结清不报“收齐”，
3653	 * 取消永远不计作到货。进度量以 BigInt 精确比较。
3654	 */
3655	function poStatus(ordered: number, effective: bigint, cancelled = 0n): string {
3656	  const remaining = BigInt(ordered) - effective - cancelled;
3657	  if (cancelled === 0n) {
3658	    if (effective === 0n) return '未到货';
3659	    if (remaining > 0n) return '部分到货';
3660	    return '收齐';
3661	  }
3662	  if (remaining > 0n) return effective === 0n ? '未到货（仍待收）' : '部分到货（仍待收）';
3663	  return effective === BigInt(ordered) ? '收齐' : '已结清（含取消）';
3664	}
3665	
3666	function printPurchase(store: Store, poId: string, po: PurchaseRecord): void {
3667	  const { effective, returned, cancelled, remaining } = purchaseProgress(store, poId);
3668	  const revOfOrig = nullProto<Record<string, string>>();
3669	  for (const [revId, rec] of Object.entries(store.reversals)) revOfOrig[rec.orig] = revId;
3670	  // 该采购单是否存在取消/退货/转单记录（含已冲销）：无相关记录的采购单展示行为保持不变
3671	  const cancelIds = Object.keys(store.cancels)
3672	    .filter((id) => store.cancels[id].poId === poId)
3673	    .sort();
3674	  const hasCancels = cancelIds.length > 0;
3675	  const returnIds = Object.keys(store.returns)
