1397	    throw new UsageError('用法：count <单据编号> --wh <仓库> --item <商品编号:预期账面量:实盘量> [...]');
1398	  if (args.flags['--wh'] === undefined) throw new UsageError('盘点单必须提供 --wh <仓库>');
1399	
1400	  const items = new Map<string, CountItem>();
