      stockMap[wh] = getStock(store.stock, pid, wh);
      pendMap[wh] = comboByKey.get(`${pid}\0${wh}`)!.pending.toString();
    }
    snapRules[pid] = ruleMap;
    snapStock[pid] = stockMap;
    snapPending[pid] = pendMap;
