resolve({
  async release(): Promise<void> {
    // 释放顺序必须是“先把路径改名移走、再关闭监听”：若先关监听，等待者
    // 可能在本进程改名前就在原路径上建立新占用，本进程随后会误删新占用。
    // 改名后再次探活被移走的套接字——只要仍能连上，就说明本进程仍在监听，
    // 删除改名副本不影响任何人；若探活不明（unknown）保守保留改名副本，
    // 绝不删除。随后才关闭监听，原协调点已不存在本进程的路径。
    const trash = `${path}.reclaim.${process.pid}.${++releaseSeq}`;
    let moved = false;
    try {
      renameSync(path, trash);
      moved = true;
    } catch {
      /* 路径已不在：可能被异常流程处理，直接关闭监听即可 */
    }
    if (moved) {
      const probe = await probeSocket(trash, LOCK_PROBE_TIMEOUT_MS);
      if (probe === 'alive') {
        try {
          unlinkSync(trash); // 确认是本进程监听：安全删除
        } catch {
          /* 删除失败则遗留，后续按已退出进程回收 */
        }
      }
      // probe 为 dead/unknown 时不删除：dead 不应出现（自己还在监听），
      // 出现或不明时都保留副本，避免误删可能属于别人的套接字。
    }
    await new Promise<void>((res) => {
      worker.once('message', (mm: { type: string }) => mm.type === 'closed' && res());
      worker.postMessage('release');
    });
    if (moved) {
      // 关闭监听后兜底：若之前因不明未删副本，此时本进程已无监听，
      // 再次探活确认仍无别人（别人不可能监听一个随机改名路径）后删除。
      try {
        const p = await probeSocket(trash, LOCK_PROBE_TIMEOUT_MS);
        if (p === 'dead') unlinkSync(trash);
      } catch {
        /* 保留副本，无害 */
      }
    }
    await worker.terminate().catch(() => {});
  },
});

