cd /tmp && cat > holder-real.mjs <<'EOF'
import { Worker } from 'node:worker_threads';
import { once } from 'node:events';
import { unlinkSync } from 'node:fs';
const path=process.argv[2]; const holdMs=Number(process.argv[3]||4000);
const code = `
const {parentPort,workerData}=require('node:worker_threads');
const net=require('node:net');
process.on('uncaughtException',()=>{});
const server=net.createServer((conn)=>{conn.on('error',()=>{});conn.destroy()});
server.on('error',(e)=>parentPort.postMessage({type:'error',code:e.code}));
server.listen({path:workerData.path,exclusive:true,backlog:1024},()=>parentPort.postMessage({type:'ready'}));
parentPort.on('message',(m)=>{if(m==='release')server.close(()=>parentPort.postMessage({type:'closed'}))});
`;
const w=new Worker(code,{eval:true,workerData:{path}});
w.on('exit',c=>{try{require('fs').appendFileSync(process.argv[2]+'.diag','WORKER EXIT '+c+'\n')}catch{}});
const [m]=await once(w,'message');
if(m.type!=='ready'){console.log('ERR',m.code);process.exit(1)}
const sa=new Int32Array(new SharedArrayBuffer(4));
const end=Date.now()+holdMs;while(Date.now()<end)Atomics.wait(sa,0,0,20);
EOF
cat > prober-real.mjs <<'EOF'
import net from 'node:net';
const path=process.argv[2]; const durMs=Number(process.argv[3]||3500);
let alive=0,dead=0,unk=0;
const end=Date.now()+durMs;
function probe(){return new Promise(res=>{let d=false;const s=net.connect({path});
 s.once('connect',()=>{alive++;s.destroy();res()});
 s.once('error',e=>{if(e.code==='ECONNREFUSED'||e.code==='ENOENT')dead++;else unk++;res()});
 setTimeout(()=>{unk++;res()},250).unref();});}
while(Date.now()<end){await probe()}
console.log(`alive=${alive} dead=${dead} unk=${unk}`);
EOF
P="$PWD/pr.sock"; rm -f "$P" "$P.diag"
node holder-real.mjs "$P" 4500 & H=$!
sleep 0.5
for i in $(seq 1 7); do node prober-real.mjs "$P" 3500 & done
wait
echo "--- diag:"; cat "$P.diag" 2>/dev/null || echo "(no worker exit)"
pkill -9 -f holder-real 2>/dev/null; true

