/**
 * 回收一个已无监听者的套接字：改名移走后再次探活被移走的套接字。只有仍连不上
 * 才确认无主并删除；若移走后能连上（属于存活占用者，理论上不应发生，作为防
 * 线）立即改名还原并返回 false。返回 true 表示原协调点已清空，可立即占用。
 */
async function reclaimDeadSocket(path: string): Promise<boolean> {
  const trash = `${path}.reclaim.${process.pid}.${++releaseSeq}`;
  try {
    renameSync(path, trash);
  } catch {
    return false; // 别人已抢先回收或占用者已自行释放：下一轮重新判断
  }
  const r = await probeSocket(trash, LOCK_PROBE_TIMEOUT_MS);
  if (r === 'alive' || r === 'unknown') {
    try {
      renameSync(trash, path); // 存活占用：原样还原，绝不接管
    } catch {
      /* 原路径已被占用者或他人重建：无法还原时也绝不删除该套接字 */
    }
    return false;
  }
  try {
    unlinkSync(trash);
  } catch {
    /* 删除失败下一轮会再次回收 */
  }
  return true;
}

